//! `@NODE@` — generated by `nros new` from the `server` template.
//!
//! Serves `example_interfaces/srv/AddTwoInts` on `/add_two_ints`.
//!
//! `register()` declares the node and its entities; `on_callback` (and `tick`,
//! where the role has one) is the body. `main.rs`'s `nros::main!()` and the
//! board own init, the executor, RMW registration and the spin loop.

#![no_std]

use example_interfaces::srv::{AddTwoInts, AddTwoIntsRequest, AddTwoIntsResponse};
use nros::{
    Callback, CallbackCtx, Component, DeclarativeNode, ExecutableNode, NodeContext, NodeOptions,
    NodeResult,
};
use nros_log::{Logger, log_info};

static LOGGER: Logger = Logger::new("@NODE@");

pub struct AddTwoIntsServer;

impl Component for AddTwoIntsServer {
    const NAME: &'static str = "@NODE@";

    const ENTITY_BOUNDS: nros::EntityBounds = nros::EntityBounds::exact(0, 1, 0, 0, 0);

    fn register(ctx: &mut NodeContext<'_>) -> NodeResult<()> {
        nros_log::register_logger(&LOGGER);
        let mut node = ctx.create_node(NodeOptions::new("@NODE@"))?;
        let _srv = node.create_service_server_for_name_with_callback::<AddTwoInts>(
            "/add_two_ints",
            "handle_add",
        )?;
        log_info!(&LOGGER, "Waiting for service requests");
        Ok(())
    }
}

impl ExecutableNode for AddTwoIntsServer {
    type State = ();
    // phase-521 W6 — no `tick`, so the entry may park past 10 ms.
    const HAS_TICK: bool = false;

    fn init() -> Self::State {}

    fn on_callback(_state: &mut Self::State, callback: Callback<'_>, ctx: &mut CallbackCtx<'_>) {
        if callback.as_str() == "handle_add" {
            if let Ok(req) = ctx.message::<AddTwoIntsRequest>() {
                log_info!(&LOGGER, "Incoming request");
                log_info!(&LOGGER, "a: {} b: {}", req.a, req.b);
                let reply = AddTwoIntsResponse { sum: req.a + req.b };
                let _ = ctx.reply::<AddTwoIntsResponse, 64>(&reply);
            }
        }
    }
}

nros::node!(AddTwoIntsServer);
